package com.pratik.imagetap;
import android.accessibilityservice.*;import android.content.*;import android.graphics.*;import android.os.*;import android.util.DisplayMetrics;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w412dp-h892dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ActionReleaseTest {
 public static class Recorder extends TapService {int sent,global=-1;boolean accept=true;GestureDescription gesture;GestureResultCallback callback;@Override protected boolean sendTapGesture(GestureDescription g,GestureResultCallback cb){sent++;gesture=g;callback=cb;return accept;}@Override protected boolean sendNavigationAction(int a){global=a;return accept;}}
 Context c;Recorder svc;DisplayMetrics dm;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("config",0).edit().putBoolean("reduceMotion",true).commit();}
 @After public void cleanup(){if(svc!=null){svc.stopSession("test");svc.onDestroy();}}
 File image(Context scope)throws Exception{Bitmap b=Bitmap.createBitmap(32,32,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);File f=TargetStore.save(scope,b);b.recycle();return f;}
 void service(ActionType... actions)throws Exception{svc=Robolectric.buildService(Recorder.class).create().get();svc.getSharedPreferences("config",0).edit().putBoolean("tap",true).putBoolean("confirm",false).putInt("similarity",96).commit();Release67Test.set(svc,"prefs",svc.getSharedPreferences("config",0));WindowManager wm=(WindowManager)svc.getSystemService(Context.WINDOW_SERVICE);Release67Test.set(svc,"wm",wm);Method panel=TapService.class.getDeclaredMethod("showPanel");panel.setAccessible(true);panel.invoke(svc);Release67Test.set(svc,"running",true);List<File> targets=(List<File>)Release67Test.get(svc,"targets");for(ActionType a:actions)targets.add(image(ActionType.scope(c,a)));Release67Test.set(svc,"latched",new boolean[actions.length]);Release67Test.set(svc,"missing",new int[actions.length]);dm=new DisplayMetrics();wm.getDefaultDisplay().getRealMetrics(dm);SystemClock.sleep(1000);}
 void finish(VisionMatcher.Hit... hits)throws Exception{boolean[] checked=new boolean[hits.length];Arrays.fill(checked,true);Method m=TapService.class.getDeclaredMethod("finish",VisionMatcher.Hit[].class,boolean[].class,int.class,int.class,int.class,double.class,String.class,boolean.class,String.class,long.class,boolean.class);m.setAccessible(true);m.invoke(svc,hits,checked,dm.widthPixels,dm.heightPixels,(Integer)Release67Test.get(svc,"generation"),10.2,"[]",true,"",SystemClock.uptimeMillis(),false);}
 VisionMatcher.Hit hit(int x,double score){return new VisionMatcher.Hit(x,500,24,24,score,96);}
 @Test public void strongestWinsEvenIfLowerMatchWasBeingConfirmed()throws Exception{service(ActionType.TAP,ActionType.TAP);Release67Test.set(svc,"confirmId",0);finish(hit(350,97),hit(550,99));assertEquals(1,svc.sent);RectF bounds=new RectF();svc.gesture.getStroke(0).getPath().computeBounds(bounds,true);assertEquals(562,bounds.left,.1);}
 @Test public void tiesAreStableAndOnlyOneActionRuns()throws Exception{service(ActionType.TAP,ActionType.BACK);finish(hit(350,99),hit(550,99));assertEquals(1,svc.sent);assertEquals(-1,svc.global);}
 @Test public void allSwipeDirectionsDispatchRealPaths()throws Exception{for(ActionType a:new ActionType[]{ActionType.LEFT,ActionType.RIGHT,ActionType.UP,ActionType.DOWN}){service(a);finish(hit(500,99));assertEquals(a.label,1,svc.sent);PathMeasure measure=new PathMeasure(svc.gesture.getStroke(0).getPath(),false);float[] start=new float[2],end=new float[2];measure.getPosTan(0,start,null);measure.getPosTan(measure.getLength(),end,null);if(a==ActionType.LEFT)assertTrue(end[0]<start[0]);if(a==ActionType.RIGHT)assertTrue(end[0]>start[0]);if(a==ActionType.UP)assertTrue(end[1]<start[1]);if(a==ActionType.DOWN)assertTrue(end[1]>start[1]);assertEquals(350,svc.gesture.getStroke(0).getDuration());svc.callback.onCompleted(svc.gesture);assertEquals(1L,Release67Test.get(svc,"taps"));svc.stopSession("test");svc.onDestroy();svc=null;}}
 @Test public void centreSwipeUsesImageOnlyAsTrigger()throws Exception{service(ActionType.RIGHT);svc.getSharedPreferences("config",0).edit().putBoolean("swipeFromCentre",true).commit();finish(hit(650,99));assertEquals(1,svc.sent);float[] start=new float[2];new PathMeasure(svc.gesture.getStroke(0).getPath(),false).getPosTan(0,start,null);assertEquals(dm.widthPixels/2,start[0],.1);assertEquals(dm.heightPixels/2,start[1],.1);}
 @Test public void backAndHomeUseGlobalActionsNotTaps()throws Exception{service(ActionType.BACK,ActionType.HOME);finish(hit(350,99),null);assertEquals(AccessibilityService.GLOBAL_ACTION_BACK,svc.global);assertEquals(0,svc.sent);SystemClock.sleep(500);finish(null,hit(550,99));assertEquals(AccessibilityService.GLOBAL_ACTION_HOME,svc.global);assertEquals(2L,Release67Test.get(svc,"taps"));}
 @Test public void rejectedNavigationDoesNotCountOrLatch()throws Exception{service(ActionType.HOME);svc.accept=false;finish(hit(350,99));assertEquals(0L,Release67Test.get(svc,"taps"));assertFalse(((boolean[])Release67Test.get(svc,"latched"))[0]);assertEquals(-1L,Release67Test.get(svc,"lastDispatchedFrame"));}
 @Test public void previewAndPauseBlockNavigation()throws Exception{service(ActionType.BACK);svc.getSharedPreferences("config",0).edit().putBoolean("tap",false).commit();finish(hit(350,99));assertEquals(-1,svc.global);svc.getSharedPreferences("config",0).edit().putBoolean("tap",true).commit();((SessionPause)Release67Test.get(svc,"pause")).manual=true;finish(hit(350,99));assertEquals(-1,svc.global);}
 @Test public void legacyTapAndOtherActionsKeepIndependentSlots()throws Exception{File legacy=image(c);assertEquals("targets",legacy.getParentFile().getName());Context left=ActionType.scope(c,ActionType.LEFT);image(left);PresetStore.copyCurrent(left,1,"Scroll feed");PresetStore.open(left,1);ActionType.select(c,ActionType.HOME);assertTrue(TargetStore.files(c).isEmpty());assertTrue(legacy.exists());assertEquals(2,TargetStore.allActiveFiles(c).size());assertEquals(0,PresetStore.active(ActionType.scope(c,ActionType.TAP)));assertEquals(1,PresetStore.active(left));assertEquals("Scroll feed",PresetStore.name(left,1));}
 @Test public void actionArchivePreservesActionAndRejectsWrongCollection()throws Exception{Context left=ActionType.scope(c,ActionType.LEFT);image(left);ByteArrayOutputStream out=new ByteArrayOutputStream();PresetArchive.exportSlot(left,0,out);try(PresetArchive.Staged s=PresetArchive.stage(c,new ByteArrayInputStream(out.toByteArray()))){assertEquals(ActionType.LEFT,s.action);try{PresetArchive.install(c,s,1,PresetStore.folder(c,1).getName());fail();}catch(IOException expected){}PresetArchive.install(left,s,1,PresetStore.folder(left,1).getName());assertEquals(1,TargetStore.files(left).size());assertTrue(TargetStore.files(c).isEmpty());}}
 @Test public void oldSharedPresetsImportAsTap()throws Exception{image(c);ByteArrayOutputStream out=new ByteArrayOutputStream();PresetArchive.exportSlot(c,0,out);Map<String,byte[]> entries=PresetArchiveTest.entries(out.toByteArray());JSONObject j=new JSONObject(new String(entries.get("manifest.json"),java.nio.charset.StandardCharsets.UTF_8));j.put("version",1);j.remove("action");entries.put("manifest.json",j.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));try(PresetArchive.Staged s=PresetArchive.stage(c,new ByteArrayInputStream(PresetArchiveTest.zip(entries)))){assertEquals(ActionType.TAP,s.action);}}
 @Test public void geometryClampsAndDetectsOverlayIntersections(){ActionGesture g=new ActionGesture(ActionType.RIGHT,900,500,1000,1600,35,2000);assertEquals(998,g.endX,0);assertEquals(1000,g.duration);assertTrue(g.crosses(950,480,980,550));assertFalse(g.crosses(950,600,980,650));assertTrue(new ActionGesture(ActionType.LEFT,4,500,1000,1600,35,350).tooShort());}
 @Test public void hubOpensEveryActionAndRetainsPresetTools()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();Field tab=MainActivity.class.getDeclaredField("tab"),open=MainActivity.class.getDeclaredField("actionCollectionOpen");tab.setAccessible(true);open.setAccessible(true);Method render=MainActivity.class.getDeclaredMethod("render");render.setAccessible(true);tab.set(a,1);render.invoke(a);AutoBashUiTest.save(Release67Test.root(a),"actions68",824,1656);for(ActionType type:ActionType.values()){assertNotNull(AutoBashUiTest.find(Release67Test.root(a),type.label));}ActionType.select(a,ActionType.LEFT);open.set(a,true);render.invoke(a);assertNotNull(AutoBashUiTest.find(Release67Test.root(a),"Swipe left targets"));assertNotNull(AutoBashUiTest.find(Release67Test.root(a),"Presets"));AutoBashUiTest.save(Release67Test.root(a),"swipe-targets68",824,1656);a.finish();}
 @Test public void distinctEffectsRenderAndFadeWithoutInterceptingTouches()throws Exception{for(ActionType type:ActionType.values()){FocusOverlay overlay=new FocusOverlay(c);overlay.preferences(false,true);overlay.action(type,new ActionGesture(type,400,500,824,1656,35,350));overlay.layout(0,0,824,1656);assertFalse(overlay.isClickable());AutoBashUiTest.save(overlay,"effect-"+type.id,824,1656);SystemClock.sleep(800);Bitmap blank=Bitmap.createBitmap(824,1656,Bitmap.Config.ARGB_8888);overlay.draw(new Canvas(blank));int[] pixels=new int[824*1656];blank.getPixels(pixels,0,824,0,0,824,1656);for(int pixel:pixels)assertEquals(0,Color.alpha(pixel));blank.recycle();}}
}
